create extension if not exists vector;
create table if not exists users (id uuid primary key, email text unique not null, password_hash text not null, name text not null, created_at timestamptz default now());
create table if not exists communities (id uuid primary key, user_id uuid references users(id) on delete cascade, name text not null, source text not null check(source in ('whatsapp','telegram','demo')), created_at timestamptz default now());
create table if not exists messages (id uuid primary key, community_id uuid references communities(id) on delete cascade, sender text not null, sent_at timestamptz, raw_text text not null, clean_text text not null, urls jsonb default '[]', content_hash text not null, category text, summary text, entities jsonb default '{"projects":[],"skills":[],"intents":[]}', embedding vector(384), processed boolean default false, created_at timestamptz default now(), unique(community_id, content_hash));
create table if not exists listening_intents (id uuid primary key, user_id uuid references users(id) on delete cascade, title text not null, description text not null, embedding vector(384), threshold float default .5, is_active boolean default true, created_at timestamptz default now());
create table if not exists matches (id uuid primary key, intent_id uuid references listening_intents(id) on delete cascade, message_id uuid references messages(id) on delete cascade, score float not null, notified boolean default false, seen boolean default false, created_at timestamptz default now(), unique(intent_id,message_id));
create table if not exists jobs (id uuid primary key, community_id uuid references communities(id) on delete cascade, status text not null default 'pending', total_messages integer default 0, processed_messages integer default 0, error text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists notifications (id uuid primary key, user_id uuid references users(id) on delete cascade, match_id uuid references matches(id) on delete cascade, title text not null, body text not null, read boolean default false, created_at timestamptz default now());
create index if not exists messages_embedding_hnsw on messages using hnsw (embedding vector_cosine_ops);
create index if not exists intents_embedding_hnsw on listening_intents using hnsw (embedding vector_cosine_ops);
